// ============================================================
// คัดกรองและจัดข้อมูลก่อนลง Google Sheets
// ============================================================
// เพิ่มจากคลิปต้นฉบับ:
//   - ตัดร้านที่ไม่มีชื่อ (ข้อมูลเสีย)
//   - ตัดร้านซ้ำ (Apify บางทีคืนซ้ำเมื่อค้นหลายคำ)
//   - บันทึกว่าแถวนี้มาจากคำค้นอะไร พื้นที่ไหน วันที่เท่าไหร่
//   - จัดรูปแบบเบอร์โทรให้โทรออกได้เลย
// ============================================================

const form = $('ฟอร์มกรอกคำค้นหา').first().json;
const searchTerm = form['คำค้นหา'] || '';
const searchArea = form['พื้นที่'] || '';
const today = new Date().toISOString().slice(0, 10);

// จัดเบอร์โทรไทยให้อยู่ในรูปที่กดโทรได้
function cleanPhone(raw) {
  if (!raw) return '';
  let p = String(raw).replace(/[^0-9+]/g, '');
  if (p.startsWith('+66')) p = '0' + p.slice(3);   // +66812345678 → 0812345678
  else if (p.startsWith('66') && p.length > 10) p = '0' + p.slice(2);
  return p;
}

const seen = new Set();
const rows = [];

for (const item of $input.all()) {
  const d = item.json;

  // ข้ามข้อมูลเสีย
  if (!d.title) continue;

  // กันซ้ำ — ใช้ placeId ถ้ามี ไม่มีก็ใช้ชื่อ+ที่อยู่
  const key = d.placeId || `${d.title}|${d.address || ''}`;
  if (seen.has(key)) continue;
  seen.add(key);

  const phone = cleanPhone(d.phoneUnformatted || d.phone);

  rows.push({
    json: {
      'ชื่อร้าน': d.title || '',
      'ประเภท': d.categoryName || '',
      'ที่อยู่': d.address || d.street || '',
      'เบอร์โทร': phone,
      'เว็บไซต์': d.website || '',
      'คะแนน': d.totalScore ?? d.score ?? '',
      'จำนวนรีวิว': d.reviewsCount ?? '',
      'เวลาทำการ': Array.isArray(d.openingHours)
        ? d.openingHours.map(h => `${h.day} ${h.hours}`).join(' / ')
        : '',
      'ลิงก์ Maps': d.url || '',
      'มีเบอร์โทร': phone ? 'มี' : 'ไม่มี',
      'คำค้นหา': searchTerm,
      'พื้นที่': searchArea,
      'วันที่ดึง': today,
    },
  });
}

if (rows.length === 0) {
  throw new Error('ไม่พบข้อมูลร้านเลย — ลองเปลี่ยนคำค้นหาหรือพื้นที่ให้กว้างขึ้น');
}

// เรียงให้ร้านที่มีเบอร์โทรขึ้นก่อน (ติดต่อได้จริง = มีค่ากว่า)
rows.sort((a, b) => (b.json['เบอร์โทร'] ? 1 : 0) - (a.json['เบอร์โทร'] ? 1 : 0));

return rows;
